(function() {
    'use strict';

    class Logi611Adapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Multimodal Logistics and Risk Mitigation';
            this.version = '1.1.0';
            this.ORDER_VALUE = 500;
            this.GROSS_MARGIN = 100;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cumulativeCost: 0,
                    delayDays: 0,
                    expectedLoss: 0,
                    projectedProfit: this.GROSS_MARGIN,
                    route: null,
                    customerApproval: null,
                    insurance: null,
                    transshipment: null,
                    weatherChoice: null,
                    customsChoice: null,
                    damageEvent: false,
                    insuranceCovered: true,
                    profitHistory: [],
                    costHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    route: 'A',
                    approval: 'none',
                    insurance: 'allrisk',
                    transshipment: 'deposito',
                    weather: 'continue',
                    customs: 'wait',
                    claim: 'close'
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var round = state.currentPeriod || 1;
            var ds = state.domainState || {};
            var T = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t.bind(window.mySimulation) : function(k){return k;};

            var titleEl = document.getElementById('roundTitle');
            var briefEl = document.getElementById('briefingText');

            var groups = ['group_route','group_approval','group_insurance','group_transshipment','group_weather','group_customs','group_claim'];
            groups.forEach(function(g){ var el = document.getElementById(g); if (el) el.style.display = 'none'; });

            var show = function(id){ var el = document.getElementById(id); if (el) el.style.display = 'block'; };

            if (round === 1) {
                if (titleEl) titleEl.innerHTML = T('round1_title');
                if (briefEl) briefEl.innerHTML = T('round1_brief');
                show('group_route');
                show('group_approval');
            } else if (round === 2) {
                if (titleEl) titleEl.innerHTML = T('round2_title');
                if (briefEl) briefEl.innerHTML = T('round2_brief');
                show('group_insurance');
                if (ds.route === 'B') show('group_transshipment');
            } else if (round === 3) {
                if (titleEl) titleEl.innerHTML = T('round3_title');
                if (briefEl) briefEl.innerHTML = T('round3_brief');
                show('group_weather');
                show('group_customs');
            } else {
                if (titleEl) titleEl.innerHTML = T('round4_title');
                if (briefEl) briefEl.innerHTML = T('round4_brief');
                show('group_claim');
            }
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var round = state.currentPeriod || 1;

            if (round === 1) {
                var r = document.getElementById('routeInput');
                var a = document.getElementById('approvalInput');
                if (r) decisions.route = r.value;
                if (a) decisions.approval = a.value;
            } else if (round === 2) {
                var ins = document.getElementById('insuranceInput');
                if (ins) decisions.insurance = ins.value;
                if (state.domainState.route === 'B') {
                    var tr = document.getElementById('transInput');
                    if (tr) decisions.transshipment = tr.value;
                } else {
                    decisions.transshipment = 'none';
                }
            } else if (round === 3) {
                var w = document.getElementById('weatherInput');
                var c = document.getElementById('customsInput');
                if (w) decisions.weather = w.value;
                if (c) decisions.customs = c.value;
            } else {
                decisions.claim = 'close';
            }
            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var ds = state.domainState;
            var d = state.decisions;
            var roundCost = 0;
            var roundDelay = 0;
            var roundLoss = 0;
            var notes = '';

            if (round === 1) {
                ds.route = d.route;
                ds.customerApproval = d.approval;
                if (d.route === 'A') {
                    roundCost = 50;
                    roundLoss = 37.5;
                    notes = 'Route A selected. Baseline logistics cost COP 50M. Expected shock/theft loss COP 37.5M.';
                } else {
                    roundCost = 35;
                    roundDelay = 2;
                    roundLoss = 15;
                    if (d.approval === 'request') {
                        notes = 'Route B selected. Customer approval requested for 6-day timeline.';
                    } else {
                        notes = 'Route B selected without customer approval. Penalty exposure COP 200M.';
                    }
                }
            } else if (round === 2) {
                ds.insurance = d.insurance;
                ds.transshipment = d.transshipment;
                if (d.insurance === 'named') {
                    roundCost = 2.5;
                    ds.insuranceCovered = false;
                    roundLoss = 5;
                    notes = 'Named peril insurance. Moisture damage not covered. Residual expected loss COP 5M.';
                } else if (d.insurance === 'allrisk') {
                    roundCost = (ds.route === 'B') ? 3.5 : 4;
                    ds.insuranceCovered = true;
                    roundLoss = -15;
                    notes = 'All-risk insurance. Expected uninsured loss mitigated.';
                } else {
                    roundCost = 5;
                    ds.insuranceCovered = true;
                    roundLoss = -18;
                    notes = 'Enhanced all-risk with shock/vibration rider. Maximum protection.';
                }
                if (ds.route === 'B') {
                    if (d.transshipment === 'deposito') {
                        roundCost += 0.6;
                        roundLoss += 10;
                        notes += ' Depósito Central selected: 2% damage risk at transshipment.';
                    } else {
                        roundCost += 1.5;
                        roundLoss += 2.5;
                        notes += ' LogíMax private hub selected: 0.5% damage risk.';
                    }
                }
            } else if (round === 3) {
                ds.weatherChoice = d.weather;
                ds.customsChoice = d.customs;
                if (ds.route === 'A') {
                    if (d.weather === 'continue') {
                        roundDelay += 0.5; roundLoss += 5;
                        notes = 'Continued on main road through Cauca Valley. Minor delay plus residual shock risk.';
                    } else if (d.weather === 'divert') {
                        roundDelay += 0.33;
                        notes = 'Diverted to secondary road. Adds 8 hours, avoids landslide zone.';
                    } else {
                        roundDelay += 1;
                        notes = 'Stopped in Cali. Safe but adds 24 hours.';
                    }
                } else {
                    if (d.weather === 'continue') {
                        roundDelay += 0.5;
                        notes = 'Accepted rail delay. Adds 12 hours.';
                    } else if (d.weather === 'divert') {
                        roundCost += 2;
                        notes = 'Paid COP 2M priority routing surcharge. Schedule held.';
                    } else {
                        roundDelay += 1;
                        notes = 'Halted train. Adds 24 hours.';
                    }
                }
                if (d.customs === 'expedite') {
                    roundCost += 1.2;
                    notes += ' Customs expedite fee COP 1.2M paid.';
                } else {
                    roundDelay += 0.75;
                    notes += ' Accepted customs inspection delay (~18 hours).';
                }
            } else {
                var penalty = 0;
                var claimRecovery = 0;
                var damageLoss = 0;
                var damageRoll = Math.random();
                var damageProbability = 0.05;
                if (ds.route === 'A') damageProbability = 0.08;
                if (ds.transshipment === 'deposito') damageProbability += 0.015;
                if (damageRoll < damageProbability) {
                    ds.damageEvent = true;
                    damageLoss = 500;
                    if (ds.insuranceCovered) {
                        claimRecovery = 499.5;
                    } else {
                        claimRecovery = 0;
                    }
                    notes = 'Cargo damage event occurred. ';
                } else {
                    notes = 'Machinery arrived intact. ';
                }

                if (ds.route === 'B' && ds.delayDays >= 2) {
                    if (ds.customerApproval === 'request') {
                        penalty = 75 * 0.35;
                        notes += 'Customer negotiation executed. Expected partial penalty COP 26M (weighted).';
                    } else {
                        penalty = 100 * ds.delayDays;
                        notes += 'Late without approval. Liquidated damages COP ' + penalty + 'M.';
                    }
                } else if (ds.delayDays > 0 && ds.route === 'A') {
                    if (ds.delayDays >= 1) {
                        penalty = 50 * ds.delayDays;
                        notes += 'Route A arrived late. Penalty COP ' + penalty + 'M.';
                    }
                }

                roundCost = penalty + damageLoss - claimRecovery;
            }

            ds.cumulativeCost += roundCost;
            ds.delayDays += roundDelay;
            ds.expectedLoss += roundLoss;
            ds.projectedProfit = this.GROSS_MARGIN - ds.cumulativeCost - Math.max(0, ds.expectedLoss);

            ds.profitHistory.push(ds.projectedProfit);
            ds.costHistory.push(ds.cumulativeCost);

            // Persist a normalized 0-100 score into domainState for the grading/reporting
            // layer (results_utils.php::express_resolveDomainScore reads
            // domainState.performance.overallScore -> domainState.score). Raw net profit
            // caps near COP 32M (best of all 144 strategies), so it is normalized via
            // _score() instead of reporting a misleading ~32/100 for optimal play.
            var _sc = this._score(ds.projectedProfit);
            ds.score = _sc;
            ds.performance = { overallScore: _sc, grade: this._grade(_sc) };

            var results = {
                period: round,
                route: ds.route || '-',
                roundCost: roundCost,
                delayDays: ds.delayDays,
                expectedLoss: ds.expectedLoss,
                cumulativeCost: ds.cumulativeCost,
                projectedProfit: ds.projectedProfit,
                score: _sc,
                overallScore: _sc,
                notes: notes
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: round + 1, domainState: ds });
            }, 500);

            return results;
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('costDisplay', 'domainState.cumulativeCost',
                (v) => 'COP ' + (Math.round(v * 10) / 10).toFixed(1) + 'M');
            uiManager.bind('delayDisplay', 'domainState.delayDays',
                (v) => (Math.round(v * 10) / 10).toFixed(1) + ' days');
            uiManager.bind('riskDisplay', 'domainState.expectedLoss',
                (v) => 'COP ' + (Math.round(v * 10) / 10).toFixed(1) + 'M');
            uiManager.bind('profitDisplay', 'domainState.projectedProfit',
                (v) => 'COP ' + (Math.round(v * 10) / 10).toFixed(1) + 'M');
        }

        getChartConfig() {
            return {
                profitChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Projected Net Profit (COP M)',
                                data: [],
                                borderColor: '#059669',
                                backgroundColor: 'rgba(5,150,105,0.12)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.2,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Cumulative Cost (COP M)',
                                data: [],
                                borderColor: '#dc2626',
                                backgroundColor: 'rgba(220,38,38,0.08)',
                                borderWidth: 2,
                                borderDash: [6, 4],
                                fill: false,
                                tension: 0.2,
                                yAxisID: 'y'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: false },
                            legend: { position: 'bottom' }
                        },
                        scales: {
                            y: { beginAtZero: true, title: { display: true, text: 'COP Millions' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.profitHistory.map((_, i) => 'R' + (i + 1));
            return {
                profitChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.profitHistory },
                        { data: state.domainState.costHistory }
                    ]
                }
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.period === 1 && state.domainState.route === 'B' && state.domainState.customerApproval === 'none') {
                return window.mySimulation.t('hint_no_approval');
            }
            if (results.period === 2 && state.domainState.insurance === 'named') {
                return window.mySimulation.t('hint_named_peril');
            }
            if (results.period === 2 && state.domainState.route === 'B' && state.domainState.transshipment === 'deposito') {
                return window.mySimulation.t('hint_deposito');
            }
            if (results.period === 4 && state.domainState.damageEvent && !state.domainState.insuranceCovered) {
                return window.mySimulation.t('hint_uninsured_loss');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.route',            label: 'Route',       i18nKey: 'col_route' },
                { key: 'results.roundCost',        label: 'Round Cost',  i18nKey: 'col_round_cost', formatter: (v) => 'COP ' + (Math.round(v*10)/10).toFixed(1) + 'M' },
                { key: 'results.delayDays',        label: 'Delay (d)',   i18nKey: 'col_delay',      formatter: (v) => (Math.round(v*10)/10).toFixed(1) },
                { key: 'results.expectedLoss',    label: 'Exp. Loss',   i18nKey: 'col_loss',       formatter: (v) => 'COP ' + (Math.round(v*10)/10).toFixed(1) + 'M' },
                { key: 'results.cumulativeCost',  label: 'Cum. Cost',   i18nKey: 'col_cum',        formatter: (v) => 'COP ' + (Math.round(v*10)/10).toFixed(1) + 'M' },
                { key: 'results.projectedProfit', label: 'Net Profit',  i18nKey: 'col_profit',     formatter: (v) => 'COP ' + (Math.round(v*10)/10).toFixed(1) + 'M' }
            ];
        }

        getPresets() { return null; }

        _score(profit) {
            // Normalize net profit (COP M) to a 0-100 grade. Anchors: best realistic play
            // (~COP 32M, top of 144 strategies) -> ~96; break-even (0) -> ~58; a COP 50M
            // loss -> 0. Raw profit tiers (>50/>60) were unreachable, so scoring is
            // recalibrated to this normalized scale (intentional, documented change).
            return Math.max(0, Math.min(100, Math.round(1.16 * profit + 58)));
        }

        _grade(score) {
            if (score >= 80) return 'Excellent';
            if (score >= 60) return 'Good';
            if (score >= 40) return 'Developing';
            return 'Beginner';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var r = last.results || {};
            var finalProfit = (typeof r.projectedProfit === 'number') ? r.projectedProfit : 0;
            var overallScore = this._score(finalProfit);
            var performance = this._grade(overallScore);
            var t = function(k) { return window.mySimulation.t(k); };
            var insights = [];
            if (overallScore >= 80) insights.push(t('sum_strong'));
            else if (overallScore >= 50) insights.push(t('sum_adequate'));
            else insights.push(t('sum_weak'));
            return {
                totalProfit: finalProfit,
                overallScore: overallScore,
                totalPeriods: history.length,
                performance: performance,
                cumulativeCost: r.cumulativeCost,
                delayDays: r.delayDays,
                expectedLoss: r.expectedLoss,
                projectedProfit: finalProfit,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            summary = summary || {};
            var t = function(k) { return window.mySimulation.t(k); };
            var money = function(v) { return 'COP ' + (Math.round(v * 10) / 10).toFixed(1) + 'M'; };
            var profit = (typeof summary.totalProfit === 'number') ? summary.totalProfit : 0;
            var score = (typeof summary.overallScore === 'number') ? summary.overallScore : this._score(profit);
            var perf = summary.performance || this._grade(score);
            var tierKey = { 'Excellent': 'tier_excellent', 'Good': 'tier_good', 'Developing': 'tier_developing', 'Beginner': 'tier_beginner' }[perf];
            var perfL = tierKey ? t(tierKey) : perf;
            var color = profit > 20 ? '#059669' : (profit > 0 ? '#d97706' : '#dc2626');
            var kpis = [
                [t('kpi_cost'), (typeof summary.cumulativeCost === 'number') ? money(summary.cumulativeCost) : '-'],
                [t('kpi_delay'), (typeof summary.delayDays === 'number') ? ((Math.round(summary.delayDays * 10) / 10).toFixed(1) + ' ' + t('days_label')) : '-'],
                [t('kpi_risk'), (typeof summary.expectedLoss === 'number') ? money(summary.expectedLoss) : '-']
            ];
            var kpiRow = kpis.map(function(k) {
                return '<span style="display:inline-block;margin:4px 10px;"><strong>' + k[1] + '</strong> ' + k[0] + '</span>';
            }).join('');
            var ins = summary.insights || [];
            var items = ins.map(function(x) { return '<li>' + x + '</li>'; }).join('');
            var insBlock = items ? ('<ul style="text-align:left;margin:12px auto 0;display:inline-block;">' + items + '</ul>') : '';
            return '<div class="completion-message text-center p-4">' +
                '<h4 style="margin-bottom:8px;">' + t('completion_heading') + '</h4>' +
                '<div style="font-size:2.4rem;font-weight:800;color:' + color + ';">' + money(profit) + '</div>' +
                '<p class="lead" style="margin:2px 0;">' + t('kpi_profit') + '</p>' +
                '<p style="font-weight:700;">' + t('overall_score_label') + ': ' + score + '/100 | <span style="color:' + color + ';">' + perfL + '</span></p>' +
                '<p class="text-muted" style="margin:8px 0;">' + kpiRow + '</p>' +
